-- Importação (idempotente) dos itens de src/data/menuData.js pra products.
-- Executado pela primeira vez em 2026-08-21 pro company_id do Cantinho do
-- Acarajé (veja README.md nesta pasta). Reexecutar é seguro: o ON CONFLICT
-- atualiza a linha existente pelo par (company_id, slug) em vez de duplicar
-- — útil se menuData.js mudar antes do frontend migrar de vez pro Supabase
-- (passo 4 em diante).
--
-- Troque o uuid abaixo se for rodar isso pra outra empresa/ambiente.

on conflict (company_id, slug) where slug is not null do update set
  name        = excluded.name,
  category    = excluded.category,
  sale_price  = excluded.sale_price,
  is_active   = excluded.is_active,
  description = excluded.description,
  tags        = excluded.tags,
  is_featured = excluded.is_featured,
  sort_order  = excluded.sort_order,
  updated_at  = now();

